package com.yihe.framework.ehr;

import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Read-only history of the shared service inbox; private AI histories are never exposed here. */
@Service
public class CommunicationHistory {
    final CommunicationService service;final EhrRepository db;final EhrService ehr;
    static final Map<String,String> CATEGORIES=new LinkedHashMap<>();
    static{CATEGORIES.put("health","健康咨询");CATEGORIES.put("report","报告解读");CATEGORIES.put("review","复查咨询");CATEGORIES.put("plan","方案沟通");CATEGORIES.put("other","其他服务");}
    public CommunicationHistory(CommunicationService service,EhrRepository db,EhrService ehr){this.service=service;this.db=db;this.ehr=ehr;}
    static class Query{String sql,source;List<Object> args=new ArrayList<>();int page,size;}
    String date(String value,boolean end){try{return LocalDate.parse(value).plusDays(end?1:0).atStartOfDay().minusHours(8).toString().replace('T',' ');}catch(Exception e){throw new EhrException(422,"日期格式应为 yyyy-MM-dd");}}
    Query query(EhrActor a,Map<String,String> q){service.staff(a);Query x=new Query();x.page=bounded(q.get("page"),1,1,100000);x.size=bounded(q.get("limit"),10,1,50);String search=q.getOrDefault("search","").trim(),start=q.getOrDefault("start",""),end=q.getOrDefault("end",""),category=q.getOrDefault("category",""),cid=q.getOrDefault("conversationId","");x.source=q.getOrDefault("source","all");require(search.length()<=100,422,"搜索条件过长");require(Arrays.asList("all","ai","human").contains(x.source),422,"回复类型无效");require(category.isEmpty()||CATEGORIES.containsKey(category),422,"会话类型无效");require(start.isEmpty()||end.isEmpty()||start.compareTo(end)<=0,422,"开始日期不能晚于结束日期");
        String messages="SELECT m.* FROM a_service_messages m WHERE 1=1";
        if(!start.isEmpty()){messages+=" AND m.created_at>=?";x.args.add(date(start,false));}if(!end.isEmpty()){messages+=" AND m.created_at<?";x.args.add(date(end,true));}
        x.sql=" FROM ("+messages+") m JOIN a_service_conversations c ON c.conversation_id=m.conversation_id JOIN a_health_records r ON r.record_id=c.record_id AND r.scope_code=c.scope_code AND r.data_mode=c.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode LEFT JOIN a_service_conversation_details d ON d.conversation_id=c.conversation_id WHERE c.scope_code=? AND c.data_mode=? AND p.deleted_at IS NULL";x.args.add(a.scope);x.args.add(a.mode);
        if(!cid.isEmpty()){service.owned(a,cid,false);x.sql+=" AND c.conversation_id=?";x.args.add(cid);}
        if(!category.isEmpty()){x.sql+=" AND COALESCE(d.category,'health')=?";x.args.add(category);}
        if(!search.isEmpty()){x.sql+=" AND (p.employee_name LIKE ? ESCAPE '!' OR p.employee_no LIKE ? ESCAPE '!' OR EXISTS(SELECT 1 FROM a_service_messages sm WHERE sm.conversation_id=c.conversation_id AND sm.body_text LIKE ? ESCAPE '!'))";for(int i=0;i<3;i++)x.args.add("%"+like(search)+"%");}
        if(!x.source.equals("all")){x.sql+=" AND EXISTS(SELECT 1 FROM a_service_messages sx WHERE sx.conversation_id=c.conversation_id AND sx.sender_role "+(x.source.equals("ai")?"IN ('ai_assisted','auto_reply')":"IN ('doctor','manager')");if(!start.isEmpty()){x.sql+=" AND sx.created_at>=?";x.args.add(date(start,false));}if(!end.isEmpty()){x.sql+=" AND sx.created_at<?";x.args.add(date(end,true));}x.sql+=")";}
        return x;
    }
    String grouped(Query x){return "SELECT c.conversation_id id,p.employee_name name,p.employee_no code,c.record_id recordId,c.service_status status,COALESCE(d.category,'health') category,d.satisfaction_score score,MIN(m.created_at) firstAt,MAX(m.created_at) latestAt,COUNT(*) messageCount,MAX(m.seq) lastSeq,SUM(m.sender_role IN ('ai_assisted','auto_reply')) aiReplies,SUM(m.sender_role IN ('doctor','manager')) humanReplies,SUM(m.sender_role='system' AND m.body_text LIKE '%已接管会话%') takeovers"+x.sql+" GROUP BY c.conversation_id,p.employee_name,p.employee_no,c.record_id,c.service_status,d.category,d.satisfaction_score";}
    public Map<String,Object> list(EhrActor a,Map<String,String> q){Query x=query(a,q);String grouped=grouped(x);long total=db.count("SELECT COUNT(*) FROM ("+grouped+") h",x.args.toArray());List<Object> args=new ArrayList<>(x.args);args.add(x.size);args.add((x.page-1)*x.size);List<Map<String,Object>> rows=db.all(grouped+" ORDER BY latestAt DESC,id DESC LIMIT ? OFFSET ?",args.toArray());for(Map<String,Object> row:rows){row.put("categoryName",CATEGORIES.get(str(row.get("category"))));Map<String,Object> last=db.one("SELECT body_text preview FROM a_service_messages WHERE conversation_id=? AND seq=?",row.get("id"),row.get("lastSeq"));row.put("preview",last==null?"":last.get("preview"));}return map("items",rows,"total",total,"page",x.page,"limit",x.size);}
    public Map<String,Object> statistics(EhrActor a,Map<String,String> q){Query x=query(a,q);Map<String,Object> stats=db.one("SELECT COUNT(*) conversations,COALESCE(SUM(aiReplies),0) aiReplies,COALESCE(SUM(humanReplies),0) humanReplies,COALESCE(SUM(takeovers>0),0) transferred,COALESCE(SUM(aiReplies>0),0) aiConversations,COALESCE(SUM(humanReplies>0),0) humanConversations,COUNT(score) ratedConversations,ROUND(100.0*SUM(score>=4)/NULLIF(COUNT(score),0),1) satisfaction FROM ("+grouped(x)+") h",x.args.toArray());
        String response="SELECT m.conversation_id,m.sender_role,m.created_at,(SELECT pm.sender_role FROM a_service_messages pm WHERE pm.conversation_id=m.conversation_id AND pm.seq<m.seq AND pm.sender_role<>'system' ORDER BY pm.seq DESC LIMIT 1) previousRole,(SELECT pt.created_at FROM a_service_messages pt WHERE pt.conversation_id=m.conversation_id AND pt.seq<m.seq AND pt.sender_role<>'system' ORDER BY pt.seq DESC LIMIT 1) previousTime"+x.sql+" AND m.sender_role<>'system'";
        Map<String,Object> rt=db.one("SELECT ROUND(AVG(TIMESTAMPDIFF(SECOND,previousTime,created_at)),1) averageSeconds,COUNT(*) responseSamples FROM ("+response+") h WHERE previousRole='employee' AND sender_role IN ('doctor','manager','ai_assisted','auto_reply')",x.args.toArray());stats.putAll(rt);stats.put("categories",CATEGORIES);return stats;
    }
    public Map<String,Object> detail(EhrActor a,String cid){service.staff(a);Map<String,Object> c=service.owned(a,cid,false),p=ehr.profile(a,str(c.get("record_id")),false);Map<String,Object> d=db.one("SELECT category,satisfaction_score score,rated_at ratedAt FROM a_service_conversation_details WHERE conversation_id=?",cid);Map<String,Object> result=map("conversation",service.view(a,c),"profile",map("name",p.get("employee_name"),"code",p.get("employee_no"),"team",p.get("team_name"),"job",p.get("position_name")),"category",d==null?"health":d.get("category"),"score",d==null?null:d.get("score"),"ratedAt",d==null?null:d.get("ratedAt"),"summary",service.summary(a,cid));
        result.put("participants",db.all("SELECT m.sender_user id,m.sender_role role,CASE WHEN m.sender_role='employee' THEN ? ELSE COALESCE(NULLIF(u.name,''),u.user_name,'服务人员') END name FROM a_service_messages m LEFT JOIN yh_user_reginfo u ON u.user_code=m.sender_user WHERE m.conversation_id=? AND m.sender_role<>'system' GROUP BY m.sender_user,m.sender_role,u.name,u.user_name",p.get("employee_name"),cid));
        List<Map<String,Object>> excerpts=db.all("SELECT body_text text FROM a_service_messages WHERE conversation_id=? AND sender_role<>'system' ORDER BY seq DESC LIMIT 12",cid);Set<String> keywords=new LinkedHashSet<>();for(Map<String,Object> m:excerpts)for(String word:new String[]{"体检报告","复查","血压","血糖","听力","肺功能","粉尘","运动","饮食","健康方案","随访","预约"})if(str(m.get("text")).contains(word))keywords.add(word);result.put("keywords",keywords);return result;
    }
    @Transactional public Map<String,Object> category(EhrActor a,String cid,String category){service.staff(a);Map<String,Object> c=service.owned(a,cid,true);require(CATEGORIES.containsKey(category),422,"会话类型无效");db.exec("INSERT INTO a_service_conversation_details(conversation_id,category,updated_at) VALUES(?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE category=VALUES(category),updated_at=UTC_TIMESTAMP(6)",cid,category);service.system(a,c,service.actorName(a)+"将会话分类设为："+CATEGORIES.get(category));return map("category",category);}
    public Map<String,Object> plans(EhrActor a,String cid){service.staff(a);Map<String,Object> c=service.owned(a,cid,false),p=ehr.profile(a,str(c.get("record_id")),false);String user=str(p.get("legacy_user_code"));if(!a.mode.equals("real")||user.isEmpty())return map("items",Collections.emptyList(),"note","暂无已关联的原系统健康方案/计划，不根据体检结果推造方案");
        Map<String,Object> u=db.one("SELECT Org_Code org FROM yh_user_reginfo WHERE user_code=?",user);require(u!=null&&db.organizationWithin(a.scope.substring(4),str(u.get("org"))),403,"原系统职工归属已变化，请核对关联");
        return map("items",db.all("SELECT up.plan_unique id,hp.plan_name name,MIN(up.plan_startdate) startDate,MAX(up.plan_enddate) endDate,COUNT(*) records FROM yh_user_healthy_plan up LEFT JOIN yh_healthy_plan hp ON hp.id=up.plan_id WHERE up.user_code=? GROUP BY up.plan_unique,up.plan_id,hp.plan_name ORDER BY startDate DESC LIMIT 20",user),"note","来源：原系统健康计划；只读展示最近20项，不执行或修改干预");}
    @Transactional public Map<String,Object> rate(EhrActor a,String cid,int score){require(a.mobile,403,"满意度只能由职工本人评价");Map<String,Object> c=service.owned(a,cid,true);require("closed".equals(c.get("service_status")),409,"服务结束后才能评价");require(score>=1&&score<=5,422,"评分为1至5星");Map<String,Object> d=db.one("SELECT satisfaction_score FROM a_service_conversation_details WHERE conversation_id=?",cid);require(d==null||d.get("satisfaction_score")==null,409,"本次会话已评价");db.exec("INSERT INTO a_service_conversation_details(conversation_id,satisfaction_score,rated_by,rated_at,updated_at) VALUES(?,?,?,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE satisfaction_score=VALUES(satisfaction_score),rated_by=VALUES(rated_by),rated_at=VALUES(rated_at),updated_at=VALUES(updated_at)",cid,score,a.user);return map("score",score);}
    static String csv(Object value){String s=str(value);if(s.matches("(?s)^[\\s]*[=+@-].*")||s.startsWith("\t")||s.startsWith("\r"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
    public byte[] export(EhrActor a,Map<String,String> q){Query x=query(a,q);List<Map<String,Object>> rows=db.all("SELECT p.employee_name name,p.employee_no code,c.conversation_id id,m.created_at time,m.sender_role role,m.body_text text,m.message_id messageId"+x.sql+" ORDER BY c.conversation_id,m.seq LIMIT 10001",x.args.toArray());require(rows.size()<=10000,413,"导出最多10000条消息，请缩小日期范围或选择单个会话");StringBuilder out=new StringBuilder("\uFEFF姓名,工号,会话编号,消息时间UTC,发送角色,消息内容,附件\r\n");Map<String,String> roles=new HashMap<>();roles.put("employee","职工");roles.put("doctor","医生");roles.put("manager","健康管理员");roles.put("ai_assisted","AI辅助人工回复");roles.put("auto_reply","自动回复");roles.put("system","服务记录");for(Map<String,Object> r:rows){List<String> attachments=new ArrayList<>();for(Map<String,Object> f:db.all("SELECT original_name FROM a_service_attachments WHERE message_id=?",r.get("messageId")))attachments.add(str(f.get("original_name")));for(Object v:Arrays.asList(r.get("name"),r.get("code"),r.get("id"),r.get("time"),roles.get(str(r.get("role"))),r.get("text"),String.join(" / ",attachments)))out.append(csv(v)).append(',');out.setLength(out.length()-1);out.append("\r\n");}return bytes(out.toString());}
}
